        (dma_128b_ar_gnt_scratch ? dma_128b_ar.cache : '0) |
        (host_axil_128b_ar_gnt_scratch ? host_axil_128b_ar.cache : '0);
    assign scratch_axi_arprot = (cpu_128b_ar_gnt_scratch ? cpu_128b_ar.prot : '0) |
