        (gpu_128b_ar_gnt_scratch ? gpu_bridge_id_ar : '0) |
        (dma_128b_ar_gnt_scratch ? dma_bridge_id_ar : '0) |
        (host_axil_128b_ar_gnt_scratch ? host_axil_bridge_id_ar : '0);


    // ================================================================
    // Slave 2: axil_periph0 (32b)
    // ================================================================
    // Multi-master (4 masters) → axil_periph0
    //   - cpu (rw)
    //   - dma (rw)
    //   - host_axil (rw)
    //   - debug_axil (rw)

    wire cpu_32b_aw_to_axil_periph0 = ((cpu_32b_aw.addr >= 32'h90000000) && (cpu_32b_aw.addr <= 32'h9000ffff));
    wire cpu_32b_ar_to_axil_periph0 = ((cpu_32b_ar.addr >= 32'h90000000) && (cpu_32b_ar.addr <= 32'h9000ffff));
    wire dma_32b_aw_to_axil_periph0 = ((dma_32b_aw.addr >= 32'h90000000) && (dma_32b_aw.addr <= 32'h9000ffff));
    wire dma_32b_ar_to_axil_periph0 = ((dma_32b_ar.addr >= 32'h90000000) && (dma_32b_ar.addr <= 32'h9000ffff));
    wire host_axil_32b_aw_to_axil_periph0 = ((host_axil_32b_aw.addr >= 32'h90000000) && (host_axil_32b_aw.addr <= 32'h9000ffff));
    wire host_axil_32b_ar_to_axil_periph0 = ((host_axil_32b_ar.addr >= 32'h90000000) && (host_axil_32b_ar.addr <= 32'h9000ffff));
    wire debug_axil_32b_aw_to_axil_periph0 = ((debug_axil_32b_aw.addr >= 32'h90000000) && (debug_axil_32b_aw.addr <= 32'h9000ffff));
    wire debug_axil_32b_ar_to_axil_periph0 = ((debug_axil_32b_ar.addr >= 32'h90000000) && (debug_axil_32b_ar.addr <= 32'h9000ffff));

    // ---- AW arbiter for axil_periph0: round-robin, lock until handshake ----
    logic [3:0] axil_periph0_aw_arb_req;
