        (axil_periph0_aw_arb_rr == 2'd1) ? (axil_periph0_aw_arb_req[1] ? 2'd1 : axil_periph0_aw_arb_req[2] ? 2'd2 : axil_periph0_aw_arb_req[3] ? 2'd3 : 2'd0) : 
