    assign axil_periph0_axi_wdata = ((cpu_32b_w_sel_axil_periph0 && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((dma_32b_w_sel_axil_periph0 && dma_32b_wvalid) ? dma_32b_w.data : '0) |
