    assign axil_periph0_axi_wstrb = ((cpu_32b_w_sel_axil_periph0 && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((dma_32b_w_sel_axil_periph0 && dma_32b_wvalid) ? dma_32b_w.strb : '0) |
